<template><el-card><template #header>账号与凭据</template><p>修改本人密码后须重新登录。口令至少14字符，最多72字节。</p><el-form label-width="120px"><el-form-item label="当前口令"><el-input v-model="oldPassword" type="password" autocomplete="current-password" /></el-form-item><el-form-item label="新口令"><el-input v-model="newPassword" type="password" autocomplete="new-password" /></el-form-item><el-button @click="change">修改本人密码</el-button></el-form></el-card><el-card v-if="isAdmin" style="margin-top:16px"><template #header>后台账号</template><el-table :data="rows"><el-table-column prop="username" label="账号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button @click="status(row)">{{row.status==='ACTIVE'?'停用':'恢复'}}</el-button><el-button @click="reset(row)">重置口令</el-button></template></el-table-column></el-table><el-pagination :current-page="page" :page-size="20" :total="total" @current-change="p=>{page=p;load()}"/><h3>创建店长、前台或教练</h3><el-form label-width="120px"><el-form-item label="账号"><el-input v-model="form.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item label="初始口令"><el-input v-model="form.password" type="password" autocomplete="new-password"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option v-for="r in ['STORE_MANAGER','STAFF','COACH']" :key="r" :label="r" :value="r"/></el-select></el-form-item><el-form-item v-if="form.role==='COACH'" label="教练档案"><el-select v-model="form.coachId"><el-option v-for="c in coaches" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item><el-button :disabled="busy" @click="create">创建</el-button></el-form></el-card></template>
<script setup>
import {ref,onMounted} from 'vue';import http from '../utils/request';import {ElMessage,ElMessageBox} from 'element-plus';import {useAuthStore} from '../store/auth';import router from '../router';
const auth=useAuthStore(),isAdmin=ref(false),rows=ref([]),coaches=ref([]),page=ref(1),total=ref(0),busy=ref(false),oldPassword=ref(''),newPassword=ref(''),form=ref({username:'',name:'',password:'',role:'STAFF',coachId:null});
function exit(){auth.logout();router.push('/login');}
async function change(){await http.post('/api/auth/password',{oldPassword:oldPassword.value,newPassword:newPassword.value});oldPassword.value='';newPassword.value='';ElMessage.success('已修改，请重新登录');exit();}
async function load(){const d=await http.get('/admin/accounts',{params:{page:page.value,size:20}});rows.value=d.list;total.value=d.total;}
async function create(){busy.value=true;try{await http.post('/admin/accounts',form.value);form.value.password='';await load();}finally{busy.value=false;}}
async function status(row){await ElMessageBox.confirm('确认更改 '+row.name+' 的状态？旧会话将失效。');await http.put('/admin/accounts/'+row.id+'/status',{status:row.status==='ACTIVE'?'DISABLED':'ACTIVE'});await load();}
async function reset(row){const {value}=await ElMessageBox.prompt('为 '+row.name+' 设置新口令，旧会话将失效','重置口令',{inputType:'password',inputValidator:v=>v&&v.length>=14||'至少14字符'});await http.post('/admin/accounts/'+row.id+'/password',{password:value});if(row.id===auth.id)exit();}
onMounted(async()=>{const me=await http.get('/api/auth/me');isAdmin.value=me.roles.includes('ADMIN');if(isAdmin.value){await load();const d=await http.get('/admin/coaches',{params:{page:1,size:100}});coaches.value=(d.list||d.records||[]).filter(c=>!c.sysUserId&&c.status==='ACTIVE');}});
</script>
